async (page) => {
  const samples = [];
  for (let i = 0; i < 110; i++) {
    const s = await page.evaluate(() => window.AO_DEBUG());
    samples.push(s);
    await page.waitForTimeout(140);
  }
  const npcs = ['sacredMage','sacredCleric','sacredPaladin','chaoticWarrior','chaoticMage','chaoticCleric','chaoticPaladin'];
  const per = {};
  for (const id of npcs) per[id] = { aimSamples: 0, aimMoving: 0, aliveSamples: 0, moved: 0, mageNear: 0, mageSamples: 0 };
  let adjacentAllies = 0, allySamples = 0;
  const positions = {};
  for (const s of samples) {
    const fs = s.fighters;
    for (const a of fs) {
      if (!a.alive) continue;
      const p = per[a.id];
      if (p) {
        p.aliveSamples++;
        const prev = positions[a.id];
        const moved = a.stepping || (prev && (prev.x !== a.x || prev.y !== a.y));
        if (moved) p.moved++;
        if (a.aiming) {
          p.aimSamples++;
          if (moved) p.aimMoving++;
        }
        if (a.id === 'sacredMage' || a.id === 'chaoticMage') {
          p.mageSamples++;
          const enemies = fs.filter(e => e.alive && e.id !== a.id && (e.id.startsWith('sacred') !== a.id.startsWith('sacred')));
          const minDist = Math.min(...enemies.map(e => Math.abs(e.x-a.x)+Math.abs(e.y-a.y)));
          if (minDist <= 1) p.mageNear++;
        }
      }
      positions[a.id] = {x:a.x, y:a.y};
    }
    for (const team of ['sacred','chaotic']) {
      const allies = fs.filter(f => f.alive && f.id.startsWith(team));
      for (let i=0;i<allies.length;i++) for (let j=i+1;j<allies.length;j++) {
        allySamples++;
        if (Math.abs(allies[i].x-allies[j].x)+Math.abs(allies[i].y-allies[j].y) <= 1) adjacentAllies++;
      }
    }
  }
  return { seconds: +(samples.length*0.14).toFixed(1), per, adjacentAllyPairsRatio: +(adjacentAllies/allySamples).toFixed(3), texts: samples.at(-1).texts.slice(-8), alive: samples.at(-1).fighters.filter(f=>f.alive).length };
}
EOF
