async (page) => {
  const snaps = [];
  for (let i = 0; i < 150; i++) {
    snaps.push(await page.evaluate(() => window.AO_DEBUG()));
    await page.waitForTimeout(120);
  }
  const per = {};
  for (const id of ['sacredMage','sacredCleric','sacredPaladin','chaoticWarrior','chaoticMage','chaoticCleric','chaoticPaladin']) {
    per[id] = { alive: 0, stepping: 0, aiming: 0, aimingStepping: 0, near: 0, distSum: 0, distN: 0 };
  }
  const staticPairs = { samples: 0, adjacentStill: 0 };
  const prev = {};
  for (const s of snaps) {
    const fs = s.fighters;
    for (const a of fs) {
      const p = per[a.id]; if (!p) continue;
      if (!a.alive) continue;
      p.alive++;
      if (a.stepping) p.stepping++;
      if (a.aiming) { p.aiming++; if (a.stepping) p.aimingStepping++; }
      const enemies = fs.filter(e => e.alive && e.id !== a.id && e.id.startsWith('sacred') !== a.id.startsWith('sacred'));
      const min = enemies.length ? Math.min(...enemies.map(e => Math.abs(e.x-a.x)+Math.abs(e.y-a.y))) : 99;
      p.distSum += min; p.distN++;
      if (min <= 1) p.near++;
    }
    for (let i=0;i<fs.length;i++) for (let j=i+1;j<fs.length;j++) {
      const A=fs[i], B=fs[j];
      if (!A.alive||!B.alive||A.id.startsWith('sacred')===B.id.startsWith('sacred')) continue;
      if (Math.abs(A.x-B.x)+Math.abs(A.y-B.y) > 1) continue;
      staticPairs.samples++;
      const pa=prev[A.id], pb=prev[B.id];
      if (pa && pb && pa.x===A.x && pa.y===A.y && pb.x===B.x && pb.y===B.y && !A.stepping && !B.stepping) staticPairs.adjacentStill++;
    }
    for (const f of fs) prev[f.id] = {x:f.x,y:f.y};
  }
  const summary = {};
  for (const [id,p] of Object.entries(per)) summary[id] = {
    movePct: p.alive ? +(p.stepping/p.alive*100).toFixed(0) : null,
    aimPct: p.alive ? +(p.aiming/p.alive*100).toFixed(0) : null,
    aimMovePct: p.aiming ? +(p.aimingStepping/p.aiming*100).toFixed(0) : null,
    nearPct: p.alive ? +(p.near/p.alive*100).toFixed(0) : null,
    avgEnemyDist: p.distN ? +(p.distSum/p.distN).toFixed(1) : null,
  };
  return { seconds: +(snaps.length*0.12).toFixed(1), summary, staticPairs, lastTexts: snaps.at(-1).texts.slice(-10) };
}
