function supportPriority(actor, ally) {
  if (!actor || !ally) return Infinity;
  const paladinBias = ally.className === 'paladin' ? (actor.className === 'cleric' ? .45 : .2) : 0;
  const distancePenalty = distance(actor, ally) * .01;
  return (ally.hp / (ally.maxHp || 1)) - paladinBias + distancePenalty;
